#include "helpers.h"

// Helper function to calculate list length
int list_length(node *root) {
    int count = 0;
    node *ptr = root;
    while (ptr != NULL) {
        count++;
        ptr = ptr->next;
    }
    return count;
}

// Function declaration matching source function
void delete_node(node **root, int id);

void setUp(void) { }
void tearDown(void) { }

void unit_test_delete_middle_node(void) {
    // Setup: Build a linked list with at least three nodes.
    // We will delete the middle node (ID=2).
    // Path conditions: root not NULL, root->ID != id, traverse loop runs,
    // ptr found (not NULL), then delete.
    int ids[] = {1, 2, 3};
    int ats[] = {0, 1, 2};
    int bts[] = {5, 4, 3};
    int priorities[] = {1, 2, 3};
    int size = 3;

    node *root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    // Verify initial list length is 3.
    int initial_length = list_length(root);
    TEST_ASSERT_EQUAL_INT(3, initial_length);

    // Test: delete node with ID 2 (middle node).
    delete_node(&root, 2);

    // Assertions:
    // 1. List length should now be 2.
    int new_length = list_length(root);
    TEST_ASSERT_EQUAL_INT(2, new_length);
    // 2. Node with ID 2 should be gone.
    node *ptr = root;
    while (ptr != NULL) {
        TEST_ASSERT_NOT_EQUAL_INT(2, ptr->ID);
        ptr = ptr->next;
    }
    // 3. The list should contain nodes 1 and 3 in order.
    ptr = root;
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(1, ptr->ID);
    ptr = ptr->next;
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(3, ptr->ID);
    TEST_ASSERT_NULL(ptr->next);

    // Cleanup.
    helper_cleanup_process_queue(&root);
}

